import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import {
  getTeacherCourses,
  getTeacherSubmissions,
  getTeacherPerformance
} from '../../api';
import {
  MetricCard, Badge, Card, SectionTitle, Spinner, difficultyVariant
} from '../../components/UI';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer
} from 'recharts';

export default function TeacherDashboard() {
  const { user } = useAuth();

  const [courses, setCourses] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [performance, setPerformance] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeCourse, setActiveCourse] = useState(null);

  useEffect(() => {
    Promise.all([
      getTeacherCourses(user.id),
      getTeacherSubmissions(user.id),
    ])
      .then(([c, s]) => {
        setCourses(c.data);
        setSubmissions(s.data);

        if (c.data.length > 0) {
          setActiveCourse(c.data[0].course_id);
          return getTeacherPerformance(user.id, c.data[0].course_id);
        }
      })
      .then((perf) => {
        if (perf) setPerformance(perf.data);
      })
      .finally(() => setLoading(false));
  }, [user.id]);

  const handleCourseChange = async (courseId) => {
    setActiveCourse(courseId);
    const res = await getTeacherPerformance(user.id, courseId);
    setPerformance(res.data);
  };

  if (loading) return <Spinner />;

  const pending = submissions.filter((s) => !s.grade);

  return (
    <div className="p-6 max-w-5xl">
      <div className="mb-6">
        <h1 className="text-xl font-medium text-gray-900">
          {user.name}
        </h1>
        <p className="text-sm text-gray-400 mt-0.5">
          Teacher dashboard
        </p>
      </div>

      {/* METRICS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
        <MetricCard label="My courses" value={courses.length} />
        <MetricCard
          label="Total students"
          value={courses.reduce(
            (s, c) => s + (c.student_count || 0),
            0
          )}
        />
        <MetricCard label="Pending grading" value={pending.length} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">

        {/* PERFORMANCE */}
        <Card>
          <div className="flex items-center justify-between mb-3">
            <SectionTitle>Class performance</SectionTitle>

            <select
              className="text-xs border border-gray-200 rounded-lg px-2 py-1"
              value={activeCourse || ''}
              onChange={(e) =>
                handleCourseChange(Number(e.target.value))
              }
            >
              {courses.map((c) => (
                <option key={c.course_id} value={c.course_id}>
                  {c.course_code}
                </option>
              ))}
            </select>
          </div>

          {performance.length > 0 ? (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={performance}>
                <XAxis dataKey="topic_name" />
                <YAxis />
                <Tooltip />
                <Bar dataKey="avg_score" fill="#1a7af0" />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <p className="text-sm text-gray-400 text-center py-8">
              No data
            </p>
          )}
        </Card>

        {/* SUBMISSIONS */}
        <Card>
          <SectionTitle>Recent submissions</SectionTitle>

          <div className="flex flex-col divide-y">
            {submissions.slice(0, 8).map((s) => (
              <div
                key={s.submission_id}
                className="flex justify-between py-2"
              >
                <div>
                  <p className="text-sm">{s.student_name}</p>
                  <p className="text-xs text-gray-400">
                    {s.assignment_title}
                  </p>
                </div>

                {s.grade ? (
                  <Badge
                    label={`${s.grade}`}
                    variant="green"
                  />
                ) : (
                  <Badge
                    label="Pending"
                    variant="amber"
                  />
                )}
              </div>
            ))}
          </div>
        </Card>

        {/* COURSES */}
        <Card className="lg:col-span-2">
          <SectionTitle>My courses</SectionTitle>

          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            {courses.map((c) => (
              <div
                key={c.course_id}
                className="border p-3 rounded"
              >
                <div className="flex justify-between mb-1">
                  <span>{c.course_code}</span>
                  <Badge
                    label={c.difficulty_level}
                    variant={difficultyVariant(c.difficulty_level)}
                  />
                </div>

                <p className="text-sm font-medium">
                  {c.course_name}
                </p>

                <div className="text-xs text-gray-400">
                  {c.student_count} students
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}
